UPDATE ACCOUNT_SYNC_STATE state
SET last_successful_synced_at = NOW(),
    last_status               = #{lastStatus},
    last_error_code           = #{lastErrorCode}
WHERE state.codef_connection_id = #{codefConnectionId}
  AND state.organization_code = #{organizationCode}
  AND EXISTS (
      SELECT 1
      FROM DAILY_BATCH_EXECUTION execution
      WHERE execution.job_name = #{jobName}
        AND execution.business_date = #{businessDate}
        AND execution.status = 'RUNNING'
        AND execution.owner_id = #{ownerId}
        AND execution.lease_token = #{leaseToken}
        AND execution.lease_until >= NOW()
  )

UPDATE ACCOUNT_SYNC_STATE state
SET last_status     = #{lastStatus},
    last_error_code = #{lastErrorCode}
WHERE state.codef_connection_id = #{codefConnectionId}
  AND state.organization_code = #{organizationCode}
  AND EXISTS (
      SELECT 1
      FROM DAILY_BATCH_EXECUTION execution
      WHERE execution.job_name = #{jobName}
        AND execution.business_date = #{businessDate}
        AND execution.status = 'RUNNING'
        AND execution.owner_id = #{ownerId}
        AND execution.lease_token = #{leaseToken}
        AND execution.lease_until >= NOW()
  )
